from __future__ import annotations

import importlib
from types import ModuleType


def require_module(name: str, *, install_name: str | None = None) -> ModuleType:
    """
    Import and return the module with the given name, raising a
    ``ModuleNotFoundError`` with an actionable message if it is not installed.
    """
    try:
        return importlib.import_module(name)
    except ImportError as error:
        install_name = install_name or name
        raise ModuleNotFoundError(
            f"{name!r} module is not installed, "
            f"it can be installed by running: 'pip install {install_name}'"
        ) from error


def require_requests() -> ModuleType:
    """
    Return the ``requests`` module, raising a ``ModuleNotFoundError`` with an
    actionable message if it is not installed.
    """
    try:
        import requests

        return requests
    except ImportError as error:
        raise ModuleNotFoundError(
            "'requests' module is not installed, "
            "it can be installed by running: 'pip install requests'"
        ) from error

